"""Materialize record-by-record middle-section data (1974 records 342--351)."""
import json,csv,re
from pathlib import Path
OUT=Path(__file__).resolve().parents[1]
T=[]; I=[]; P=[]; C=[]
def talk(record,date,speaker,pages,title,summary):
 T.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))
def item(record,pages,kind,title,notes,statement,fate,refs=(),cls='E',reconstruction=r'',literal='correct with missing hypotheses',match='exact',verification='read the result',development='none',problem='',confidence='high',speaker=None,status=''):
 n=1+sum(x['record']==record for x in I)
 d=dict(id=f'1974-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=status or 'As of November 2026, this is an established result in the stated scope; the qualification in the statement is essential.',literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth='',refs=list(refs),confidence=confidence)
 if speaker:d['speaker']=speaker
 I.append(d);return d['id']
def corr(page,place,reads,should,evidence,typ='faithful_error',applies='both'):
 C.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))
def save():
 T.sort(key=lambda x:x['record']);I.sort(key=lambda x:(x['record'],int(x['id'].split('.')[-1])))
 for rows in (T,I,P,C):
  for d in rows:
   for k,s in d.items():
    if not isinstance(s,str):continue
    s=s.replace('\textquotesingle', "'")
    s=re.sub(r'\\S(?=[IVXLCDM]+\b)',r'\\S ',s)
    s=re.sub(r'(?<=[a-z])(?=(?:19|20)\d{2}\b)', ' ', s)
    s=re.sub(r'\b(Theorem|Lemma|Example|Chapter|Appendix|September|October|November|December|June|July|August|January|February|March|April|May)(?=\d)',r'\1 ',s)
    s=re.sub(r'(?<=\d)(?=(?:September|October|November|December|June|July|August|January|February|March|April|May)\b)', ' ', s)
    s=re.sub(r'\b(at|by|from|with|to|is|in|has|than|as|of|for|only|and|before|after|received|published|record|section|sections|Section|Sections|volume|number|dimension|degree|norm|label|equal)(?=\d)',r'\1 ',s)
    s=re.sub(r'\bClass(?=[A-F]\b)','Class ',s)
    s=re.sub(r'Appendix(?=[A-Z](?:\.|\b))','Appendix ',s)
    s=re.sub(r'(published|received)(?=(?:September|October|November|December|June|July|August|January|February|March|April|May)\b)',r'\1 ',s)
    d[k]=s
 for name,rows in [('talks',T),('items',I),('problems',P)]:
  (OUT/f'middle_{name}.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
 with (OUT/'middle_corrections.csv').open('w') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(C)
 print('saved',len(T),'records',len(I),'items',len(P),'problems',len(C),'corrections')

# Record 342. Catalogue ranges are retained at talk level; items locate the actual passage.
talk(342,'1974-09-23','I. M. Gelfand','P000563-P000567','Combinatorial characteristic classes and two dilogarithm integrals',r'The opening of P000564 announces the work of Gabrielov, Gelfand and Losik in combinatorial topology and an analytic approach. It gives a non-elementary logarithmic integral, a Basel evaluation with the wrong sign, and a second, correct, golden-ratio evaluation said to come from topology. No characteristic-class construction is actually recorded. The following Giusti lecture belongs to record 341; the separately headed recap on P000566 is assigned to record 343. These are editorial passage boundaries inside overlapping catalogue page ranges.')
item(342,'P000564, opening','method','Analytic expressions in combinatorial characteristic-class calculations',r'\ru{О раб. Габриэлова, И. Гельфанда и Лосика по комбинаторной топологии}; \ru{Интересно сделать аналитически}. The logarithmic integrals are said to occur in a finite combinatorial problem.',r'The identifiable programme is to express characteristic classes of triangulated smooth manifolds by local combinatorial data, with analytic functions entering the formula. The page does not specify a triangulation, cochain, normalization, or the particular class, and hence does not state a theorem that can be reconstructed uniquely.',r'\citet[pp.~103--115]{gabrielovgelfandlosik1975computation} and \citet[pp.~186--202]{gabrielovgelfandlosik1975calculus} are the directly attributable publications in 1975 (received 2 December 1974 and 31 March 1975). Their subject and authors match; the notebook does not support an exact theorem match.',refs=['gabrielovgelfandlosik1975computation','gabrielovgelfandlosik1975calculus'],cls='A',literal='not determinable',match='partial',verification='publisher metadata checked',confidence='medium',status='As of November 2026, the publication family is identified. The particular finite combinatorial problem invoked by this paragraph remains unspecified; no new open problem is inferred.')
item(342,'P000564, first display','claim','The logarithmic integral and the Rogers dilogarithm',r'The notes write \(\int_{1-x}^{x}\{\log|t|/(1-t)+\log|1-t|/t\}\,dt\), saying it cannot be evaluated in elementary functions.',r'For \(0<x<1\), set \(L(x)=\operatorname{Li}_2(x)+\tfrac12\log x\log(1-x)\). Then the displayed integral equals \(-2[L(x)-L(1-x)]\). This is a dilogarithmic antiderivative, not an assertion that every individual special value is non-elementary.',r'This is classical dilogarithm calculus, documented with the derivative and reflection formula in \citet[Chapter II, \S1.A, pp.~23--24]{zagier2007dilogarithm}. The modern reference does not date the formula to 2007.',refs=['zagier2007dilogarithm'],literal='correct',reconstruction=r'The domain and the explicit identification with the real Rogers dilogarithm are editorial; the notebook gives only the integral.')
item(342,'P000564, Basel display','claim','The sign of the Basel integral',r'The scan explicitly has \(\int_0^1\log|1-t|\,dt/t=+\pi^2/6\), followed by a positive power-series sum.',r'The convergent improper integral is \(\int_0^1\log(1-t)\,dt/t=-\zeta(2)=-\pi^2/6\). Termwise integration of \(-\log(1-t)=\sum_{n\ge1}t^n/n\) is justified by monotone convergence.',r'The corrected identity is classical; see \citet[Eqs.~25.12.1--2]{nist2026polylogarithms}. The error is already in the handwriting, not introduced by the English translation.',refs=['nist2026polylogarithms'],literal='false as written',development='annotated')
item(342,'P000564, second definite integral','claim','A correct golden-ratio dilogarithm evaluation',r'For \(a=\sqrt5-2\), the notes give \(\int_{-a}^a\{\log|t|/(1-t)+\log|1-t|/t\}\,dt=-\pi^2/6\), adding \ru{из топологических соображений}.',r'The improper integral through \(t=0\) exists and the stated value is correct. It follows from the reflection and five-term equations for the real Rogers dilogarithm; the notebook supplies no topological argument.',r'The analytic identity reduces to classical functional equations, as in \citet[Chapter II, \S1.A]{zagier2007dilogarithm}. A complete verification and two independent numerical checks are supplied in the verification appendix. This establishes the reading without attributing our proof to the speaker.',refs=['zagier2007dilogarithm'],literal='correct',development='annotated')
corr('P000564','Basel integral and power-series explanation',r'\(\int_0^1\log|1-t|\,dt/t=\pi^2/6\).',r'\(\int_0^1\log(1-t)\,dt/t=-\pi^2/6\); put a minus sign before the positive series as well.',r'The scan has no minus sign; the integrand is strictly negative on \((0,1)\), and \(-\log(1-t)\) has the positive Taylor series. Faithful notebook error.')
save()

# Record 344: the catalogue ends at P570, but the proof continues on P571.
talk(344,'1974-09-30','Graeme Segal','P000568-P000570','Configuration spaces, scanning, and positive and negative particles',r'P000569--P000571 reports Dusa McDuff\textquotesingle s work, beginning with Segal\textquotesingle s published approximation of iterated loop spaces by configurations. It distinguishes stable homology from an actual homotopy equivalence, introduces cancellation of opposite charges, and sketches a local-to-global proof using particles that disappear at a boundary. The notation \(\mathrm{Map}\) must be read with its specified basepoints; omitting them changes the theorem. The final gluing paragraph continues beyond the catalogue\textquotesingle s last page.')
item(344,'P000569, definition and electric-field construction','construction','Unordered configurations and the electric-field map',r'\(C_k(\mathbb R^n)\) consists of unordered subsets of cardinality \(k\). Unit charges define \(f_S\), with each particle sent to infinity and infinity sent to zero, and the resulting sphere map has degree \(k\).',r'For \(n>1\), choose a decaying radial field with a pole of fixed local degree at each point of a configuration. Its one-point compactification gives a continuous map \(C_k(\mathbb R^n)\to\Omega^n_k S^n\), where the source sphere is based at infinity and the target at zero. Orient the target so that each positive pole contributes degree \(+1\); then the total degree is \(k\).',r'The construction is already explicit in \citet[\S1, p.~213]{segal1973configuration}, published in1973. Its description agrees unusually closely with the notebook.',refs=['segal1973configuration'],literal='correct with missing hypotheses',reconstruction=r'The based mapping space, n>1 for the electrostatic description, and orientation convention are made explicit. Scanning gives the corresponding construction also in dimension1.')
item(344,'P000569, homology display; P000570, stable limit','theorem','Stable homology approximation and group completion',r'\(H_i(C_k(\mathbb R^n))\cong H_i(\mathrm{Map}_k(S^n,S^n))\) for \(i\ll k\). The right-hand side is homotopically independent of \(k\), while configurations stabilize by adding particles.',r'For each fixed \(i\), scanning induces an integral-homology isomorphism \(H_i(C_k(\mathbb R^n);\mathbb Z)\to H_i(\Omega^n_kS^n;\mathbb Z)\) for all sufficiently large \(k\). Adding a particle at infinity defines stabilization after choosing an end, and translation between components of the grouplike loop space identifies their homotopy types. This is a stable homology assertion, not a finite-\(k\) homotopy equivalence.',r'\citet[\S1 and main theorem]{segal1973configuration} proves the group-completion formulation and states this consequence. The notebook gives no numerical stable range, so none is attributed to the1974 lecture.',refs=['segal1973configuration'],literal='correct with missing hypotheses')
item(344,'P000570, Fuchs intervention','remark','Configuration spaces as classifying spaces',r'Fuchs says that \(C_k(\mathbb R^n)\) gives different classifying spaces, without naming the groups or a limiting dimension.',r'Two standard instances make the remark precise: \(C_k(\mathbb R^2)\) is a classifying space for the braid group, and \(C_k(\mathbb R^\infty)\) is a classifying space for \(\Sigma_k\). For a fixed finite \(n\ge3\), the ordered configuration space is not generally contractible, so the unordered space cannot simply be identified with \(B\Sigma_k\).',r'The braid and stable symmetric-group interpretations form the background of \citet[\S1]{segal1973configuration}; the notebook itself specifies neither example. The statement is therefore an identified but only partially matched expository remark.',refs=['segal1973configuration'],speaker='D. B. Fuchs',reconstruction=r'The two examples are editorial explanations of a general remark, not transcribed assertions.',match='partial',verification='indirect',confidence='medium')
item(344,'P000570, opposite charges','definition','The topology of signed configurations',r'Finite subsets carry charges of either sign; opposite charges disappear when they meet. Components are indexed by the total charge \(k\in\mathbb Z\).',r'Let \(C(M)=\coprod_{r\ge0}C_r(M)\). Form \(C^{\pm}(M)\) from \(C(M)\times C(M)\) by cancelling a point common to the positive and negative configurations, with the quotient topology. Particles of the same sign remain distinct. For connected Euclidean space, the invariant \(\#S_+-\#S_-\) labels the path components.',r'This is McDuff\textquotesingle s positive-and-negative-particle functor, published in1975: \citet{mcduff1975configuration}. The precise quotient is also given in \citet[\S1; Example11.5]{kallel1998particles}. The notebook records its seminar circulation by30September1974.',refs=['mcduff1975configuration','kallel1998particles'],cls='B',literal='correct',verification='read the result')
item(344,'P000570, crossed comparison and corrected target','conjecture','The correct loop-space target for cancelling particles',r'A tentative \(C_k^{\pm}(\mathbb R^n)\simeq\mathrm{Map}_k(S^n,S^n)\) is labelled \ru{гипотеза}; it is immediately followed by a target \(Y_n\) of dimension \(2n\).',r'For the cancellation topology just defined, the identified target is \(Y_n=(S^n\times S^n)/\Delta(S^n)\), with the diagonal collapsed to the basepoint. Scanning gives \(C^{\pm}(\mathbb R^n)\simeq\Omega^nY_n\), componentwise with charge corresponding to degree. Replacing \(Y_n\) by \(S^n\) is not valid for this space of particles.',r'\citet{mcduff1975configuration} is the publication announced in the talk; \citet[Example11.5]{kallel1998particles} explicitly gives the quotient target and the equivalence, attributing it to McDuff. Thus the tentative sphere target is corrected by the very theory being reported, rather than retained as an open conjecture.',refs=['mcduff1975configuration','kallel1998particles'],cls='B',literal='false as written',problem='GP-1974-11',reconstruction=r'The notebook leaves Y_n unnamed. Its quotient model is identified from the later text, not read into the handwriting.',development='annotated')
item(344,'P000570, tangent-bundle compactification','construction','Scanning a manifold into a section space',r'\(C_k(M)\to\Gamma_k^{\mathrm{cpt}}(T_M^{\mathrm{comp}})\), with infinity added to each tangent fibre. A finite-range electric field is said to make the construction rigorous.',r'For a smooth \(n\)-manifold, choose a Riemannian metric and sufficiently small scanning balls. A configuration determines a compactly supported section of the fibrewise one-point compactification \(\dot TM\); outside the scanning support it is the infinity section. The component of the section space is the one containing scanned \(k\)-particle configurations. Local charts are glued through the tangent-bundle transition maps.',r'This is the scanning construction of \citet{mcduff1975configuration}; the bundle and relative-section formulation are made explicit in \citet[Theorem1.1]{kallel1998particles}. Its status in the notebook is an announcement of McDuff\textquotesingle s result, published the following year.',refs=['mcduff1975configuration','kallel1998particles'],cls='B')
item(344,'P000570, stable manifold theorem','theorem','Stable homology of configurations on manifolds',r'The manifold scanning map is said to induce a homology isomorphism for \(i\ll k\), without specifying compactness, boundary conditions or a stable range.',r'For a connected smooth open manifold of dimension at least2 that is the interior of a compact manifold with nonempty boundary, choose an end for stabilization. In each fixed degree, scanning from \(C_k(M)\) to the corresponding compactly supported section component induces an integral-homology isomorphism for all sufficiently large \(k\). The stabilized space and section space are homology equivalent. Closed-manifold and relative variants require their own formulation.',r'The stable scanning theorem originates in \citet{mcduff1975configuration}; \citet[Theorem1.1]{kallel1998particles} proves a broader particle-space formulation. The restricted open-manifold statement is sufficient to make the unqualified notebook sentence rigorous.',refs=['mcduff1975configuration','kallel1998particles'],cls='B',reconstruction=r'The stated finite-type open-manifold scope is a safe precise reconstruction. The notebook says only manifold; no assertion for arbitrary spaces or boundary conventions is inferred.',match='partial')
item(344,'P000570, failed restriction and boundary quotient','construction','Particles disappearing at a boundary',r'The map \(C(M)\to C(U)\times C(V)\) by restriction is marked discontinuous. For manifolds with boundary, \(\overline C(U)\) identifies configurations agreeing on the interior, so boundary particles disappear.',r'Cardinality changes when a particle crosses the edge of an open piece, preventing continuity into the disjoint-union configuration topology. The relative space \(C(U,\partial U)\), formed by deleting particles on \(\partial U\), gives the required continuity at the exit locus. Collar choices provide compatible restriction maps for the gluing argument.',r'The relative configuration construction is part of McDuff\textquotesingle s scanning proof; see \citet{mcduff1975configuration} and the explicit relative particle construction in \citet[\S6]{kallel1998particles}.',refs=['mcduff1975configuration','kallel1998particles'],cls='B',literal='correct with missing hypotheses')
item(344,'P000570, boundary theorem and disk proof','theorem','Relative configurations and the local disk calculation',r'For \(U\) with nonempty boundary, \(\overline C(U)\simeq\Gamma(\dot TU)\). For a disk, radially pushing points to the boundary leaves at most one particle, and both sides become \(S^n\).',r'In the relative scanning model for a compact connected smooth manifold with nonempty boundary, particles are allowed to disappear on all of the boundary and the target consists of sections with unrestricted boundary values. The local model is \(C(D^n,\partial D^n)\simeq D^n/\partial D^n\cong S^n\), while \(\Gamma(\dot TD^n)\simeq\mathrm{Map}(D^n,S^n)\simeq S^n\). For disconnected manifolds each component must meet the exit boundary.',r'This local calculation and its relative extension are the mechanism of \citet{mcduff1975configuration}; compare \citet[\S9 and Lemma11.1]{kallel1998particles}. Fixing the section to infinity on the whole boundary would instead produce a loop-space target and would change this theorem.',refs=['mcduff1975configuration','kallel1998particles'],cls='B',reconstruction=r'Connectedness, the exit boundary, and unrestricted section values at that boundary are supplied to distinguish this statement from compactly supported scanning on the interior.',match='partial',verification='read the result')
item(344,'P000571, two covering squares and homotopy lifting','method','Local-to-global proof by homotopy pullback',r'The two restriction squares for \(\overline C\) and sections are compared. Homotopies lift in the restriction maps; equivalences on \(U,V,U\cap V\) then give one on \(U\cup V\).',r'With collared manifold pieces and the appropriate relative configuration spaces, the restriction diagrams must model homotopy pullbacks (or the corresponding quasifibration sequences). An objectwise equivalence on the other three vertices then implies one on the union. A bare square of ordinary configuration spaces does not have this property; the exit-boundary construction and homotopy-lifting hypotheses do the work.',r'The proof method belongs to the scanning and quasifibration argument of \citet{mcduff1975configuration}; \citet[\S2 and \S9]{kallel1998particles} gives explicit quasifibration criteria. The notebook sketches the method but does not specify enough collars or maps to constitute a complete proof.',refs=['mcduff1975configuration','kallel1998particles'],cls='B',reconstruction=r'Homotopy pullback is the modern precise interpretation of the drawn squares; no strict sheaf property is asserted.',match='partial')
P.append(dict(id='GP-1974-11',title='The loop-space target for positive and negative particles',statement=r'Identify the homotopy type of finite signed configurations in \(\mathbb R^n\) in which opposite particles cancel, and decide whether the target is \(\Omega^nS^n\).',occurrences=['1974-344.5'],status=r'As of November2026, resolved by the McDuff model \(\Omega^n((S^n\times S^n)/\Delta S^n)\); the sphere-only target is incorrect for the stated cancellation topology. The1974 page already replaces it by an unspecified2n-dimensional target; the publication is1975. See \citet{mcduff1975configuration} and \citet[Example11.5]{kallel1998particles}.',status_date='2026-11',refs=['mcduff1975configuration','kallel1998particles']))
corr('P000569-P000570','Mapping-space target in the homology and signed-configuration displays',r'\(\mathrm{Map}_k(S^n,S^n)\) with no basepoint qualification.',r'Read the electric-field and Euclidean scanning target as based maps \(\Omega^n_kS^n\); for signed particles use based maps to the corrected quotient target.',r'The notebook explicitly fixes infinity to zero. Segal1973, p.213, specifies base-point-preserving maps. Unbased mapping spaces are different; this is a missing hypothesis, not a changed handwritten symbol.',typ='faithful_error')
corr('P000570','Tentative signed-particle sphere target',r'\(C_k^{\pm}(\mathbb R^n)\simeq\mathrm{Map}_k(S^n,S^n)\).',r'For the specified cancellation topology, use \(\Omega^n_k((S^n\times S^n)/\Delta S^n)\).',r'The scan labels the first formula a hypothesis and follows it with a2n-dimensionalY_n. McDuff\textquotesingle s target is given explicitly in Kallel1998, Example11.5. The correction is to a provisional mathematical assertion, not a transcription error.')
corr('P000571','End of Segal configuration-space record',r'Catalogue record344 stops atP000570.',r'The gluing proof continues through the opening ofP000571, before the next meeting heading onP000572.',r'P000571 continues both restriction squares and refers to the preceding theorem; no new speaker or date intervenes.',typ='provenance')
save()

# Record 343.
talk(343,'1974-09-23','I. M. Gelfand','P000565-P000570','Finite-gap Schrödinger operators, Bloch functions, and an entire-function proposal',r'P000566 is explicitly headed as Gelfand\textquotesingle s repetition of Dubrovin\textquotesingle s previous talk. It reconstructs periodic spectral bands using monodromy, then packages the finite-gap theory in a logarithmic derivative, quasimomentum, and a polynomial divisor. P000568 appends Gelfand\textquotesingle s question about entire functions of order one and a Dubrovin assertion on the zeros and poles of the Bloch function. The entire-function paragraph lacks the admissibility and normalization conditions necessary for a determinate inverse theorem.')
item(343,'P000566, opening','definition','Periodic Hill operator and bounded Bloch solutions',r'\(-y^{\prime\prime}+u(x)y=Ey\); the written periodicity is \(u(x+T)=u(y)\). The spectrum is described as the energies having bounded eigenfunctions.',r'For real \(T\)-periodic \(u\in C^\infty(\mathbb R)\), let \(L=-d^2/dx^2+u\) on \(L^2(\mathbb R)\), domain \(H^2\). Its spectrum consists precisely of real energies with a nonzero bounded solution of \(Ly=Ey\). These are generalized eigenfunctions, generally not \(L^2(\mathbb R)\) eigenvectors.',r'Classical Floquet theory, recapitulated in \citet[Chapter 2, \S1]{dubrovinmatveevnovikov1976nonlinear}; compare earlier occurrence 1973-326.2 and 1973-326.8.',refs=['dubrovinmatveevnovikov1976nonlinear'],literal='false as written',reconstruction=r'Real smooth periodic potential and operator domain are stated explicitly; the displayed u(y) is emended to u(x).')
item(343,'P000566, Novikov problem and theorem','question','Characterizing finite-gap potentials by stationary KdV',r'\ru{Проблема Новикова: когда есть конечн. число запрещ. зон?} The answer is written as a nonlinear ordinary differential equation \(K(u,u^{\prime},\ldots,u^{(2N+1)})=0\) from the KdV hierarchy.',r'A real smooth periodic potential has finitely many open bounded spectral gaps if and only if it is stationary for a nontrivial finite real linear combination of the KdV hierarchy flows (equivalently, its Schr\"odinger operator commutes with an odd-order scalar differential operator). The least nondegenerate order corresponds to the number of open gaps; a higher stationary equation need not have all its gaps open.',r'Novikov\textquotesingle s paper was received 18 February 1974 and published in 1974; see \citet[\S2]{novikov1974periodic}. The full equivalence and algebro-geometric account appear in \citet[Chapter 2, \S2]{dubrovinmatveevnovikov1976nonlinear}. This repeats the line already indexed as 1973-326.15.',refs=['novikov1974periodic','dubrovinmatveevnovikov1976nonlinear'],cls='A',problem='GP-1974-10',reconstruction=r'The phrase KdV equations is interpreted as stationary finite linear combinations, not the evolutionary PDE u_t=6uu_x-u_{xxx}. Publication within1974 is clear; precise issue-day priority relative to23September is not asserted.')
item(343,'P000566, fundamental solutions','construction','Monodromy and its discriminant',r'The normalized \(c,s\) solutions, the translation matrix \(\widehat T=(\alpha_{ij})\), \(\det\widehat T=1\), and \(\lambda^2-2\tau\lambda+1=0\) with \(2\tau=\alpha_{11}+\alpha_{22}\) are written.',r'Normalize \(c(x_0)=s^{\prime}(x_0)=1\), \(c^{\prime}(x_0)=s(x_0)=0\). The period map on the two-dimensional solution space has determinant one by the constant Wronskian. Its eigenvalues are \(\tau(E)\pm\sqrt{\tau(E)^2-1}\); every matrix entry and \(\tau\) is entire in \(E\).',r'Classical monodromy construction; \citet[Chapter 2, \S1, Eqs.~(2.1.1)--(2.1.8)]{dubrovinmatveevnovikov1976nonlinear}. Earlier occurrence: 1973-326.7.',refs=['dubrovinmatveevnovikov1976nonlinear'],literal='correct')
item(343,'P000566, band criterion and drawings','theorem','Allowed and forbidden intervals from the discriminant',r'An allowed energy has a Bloch function with \(|\lambda|=1\); \(\tau^2\le1\) is allowed and \(\tau^2>1\) forbidden. Two drawings correct the oscillation of the discriminant.',r'For the real periodic problem, \(\sigma(L)=\{E\in\mathbb R:|\tau(E)|\le1\}\). Periodic and antiperiodic eigenvalues give band endpoints. Interior critical points lie in closed gaps, and extrema alternate at levels at least1 and at most−1 respectively. A closed gap means a tangency at \(+1\) or \(-1\), not that the entire discriminant becomes constant.',r'Classical Hill spectral theory; \citet[Chapter 2, \S1]{dubrovinmatveevnovikov1976nonlinear}. The notebook\textquotesingle s later \(\max\) and \(\min\) both equal1 is a sign omission, visible after the corrected sketch.',refs=['dubrovinmatveevnovikov1976nonlinear'],literal='correct with missing hypotheses',development='annotated')
item(343,'P000566, double roots','theorem','Closed gaps have scalar monodromy',r'If \(\tau^2(E)=1\) has a multiple root, the notes infer \(\alpha_{12}=\alpha_{21}=0\), distinguishing a Jordan band edge from a diagonal one.',r'For a real periodic Hill operator, a double periodic or antiperiodic eigenvalue has two independent periodic or antiperiodic solutions, so its monodromy is \(+I\) or \(-I\). Thus both off-diagonal entries vanish in every basis; a simple edge generally has a nontrivial Jordan block. This uses the differential equation and self-adjoint boundary problem, not the characteristic polynomial of an arbitrary matrix alone.',r'Classical closed-gap criterion; \citet[Chapter 2, \S1]{dubrovinmatveevnovikov1976nonlinear}; earlier 1973-326.12.',refs=['dubrovinmatveevnovikov1976nonlinear'])
item(343,'P000566-P000567, square root','construction','Removing double branch points from the spectral curve',r'There are \(2N+1\) simple finite roots \(E_j\) of \(\tau^2-1\), the other roots are double; a radical involving \((\tau^2-1)/\prod(E-E_j)\) is called single-valued.',r'If the real periodic spectrum has exactly \(N\) open bounded gaps and distinct endpoints \(E_1<\cdots<E_{2N+1}\), then \((\tau^2(E)-1)/\prod_j(E-E_j)\) is entire with only even-order zeros, hence has an entire square root. The remaining two-sheeted compact curve is \(w^2=\prod_j(E-E_j)\), of genus \(N\).',r'The finite-gap reduction is in \citet[Chapter 2, \S\S1--2]{dubrovinmatveevnovikov1976nonlinear}. The radical must include the quotient; the handwritten overbar alone does not decide its full scope.',refs=['dubrovinmatveevnovikov1976nonlinear'],cls='A',reconstruction=r'The quotient under one square root is the mathematical reading, not a claim that the scan is unambiguous.',development='annotated')
item(343,'P000567, properties1--3','definition','The Riccati logarithmic derivative',r'\(\chi=-i\Psi^{\prime}/\Psi\); it is independent of the normalizing point \(x_0\), periodic in \(x\), and satisfies \(-i\chi^{\prime}+\chi^2+u-E=0\).',r'For a chosen nonzero Bloch solution, away from its zeros, the logarithmic derivative is independent of scalar normalization, is \(T\)-periodic, and obeys that Riccati equation. Branch choice in spectral parameter remains; independence of \(x_0\) means that the same Bloch line is selected.',r'Classical Riccati substitution, written in precisely this convention in \citet[Chapter 2, \S1, Eqs.~(2.1.10)--(2.1.12)]{dubrovinmatveevnovikov1976nonlinear}.',refs=['dubrovinmatveevnovikov1976nonlinear'])
item(343,'P000567, properties4,7,8','theorem','Amplitude and phase of a Bloch solution',r'\(\chi_I=\chi_R^{\prime}/(2\chi_R)\), \(\Psi=\sqrt{\chi_R(x_0,E)/\chi_R(x,E)}\exp(i\int_{x_0}^x\chi_R)\), and \(|\Psi|^2=\chi_R(x_0,E)/\chi_R(x,E)\) in an allowed band.',r'For real \(u,E\) with \(E\) inside an open spectral band, choose a nonreal Bloch line and its conjugate, with nonzero Wronskian. Then \(a=\operatorname{Re}\chi\) never vanishes, \(\operatorname{Im}\chi=a^{\prime}/(2a)\), and the displayed normalized amplitude-phase formula holds with a continuous square root equal to1 at \(x=x_0\). It need not hold at a band endpoint without a limiting interpretation.',r'\citet[Chapter 2, \S1, Eqs.~(2.1.12)--(2.1.14)]{dubrovinmatveevnovikov1976nonlinear} gives these formulas.',refs=['dubrovinmatveevnovikov1976nonlinear'])
item(343,'P000567, properties5--6','construction','Formal high-energy densities and parity',r'For \(E=k^2\), \(\chi\sim k+\sum_{n\ge1}\chi_n/(2k)^n\); the coefficients are differential polynomials in \(u\). The real part contains only odd inverse powers.',r'For smooth real \(u\), the formal Riccati solution with leading term \(k\) is obtained recursively. In this convention \(\chi_1=-u\), \(\chi_2=-iu^{\prime}\), \(\chi_3=u^{\prime\prime}-u^2\). Odd coefficients are real and even coefficients imaginary; even terms are total derivatives and integrate to zero over a period. A formal expansion is not a claim of convergence.',r'\citet[Chapter1, \S1 and Chapter2, Eq.~(2.1.18)]{dubrovinmatveevnovikov1976nonlinear}; compare1973-326.19.',refs=['dubrovinmatveevnovikov1976nonlinear'],reconstruction=r'The first coefficients and formal-versus-convergent distinction are supplied editorially. Signs follow the notebook\textquotesingle s chi=-i psi prime/psi convention.')
item(343,'P000567, property9','construction','Quasimomentum as a generating function',r'\(\lambda=e^{ip(E)}\), \(p(E)=\int_{x_0}^{x_0+T}\chi_R(x,E)\,dx+2\pi n\); the Euler equations for its expansion are called KdV equations.',r'For a selected Bloch branch, \(p\) is defined modulo \(2\pi\). Its high-energy expansion yields integrals of local differential polynomials invariant under isospectral KdV flows. Hamiltonian evolution generated by these integrals gives the KdV hierarchy; critical points of finite linear combinations give stationary equations. The Euler--Lagrange equation alone is not the evolutionary KdV equation.',r'\citet[Chapter2, Eq.~(2.1.15) and \S2]{dubrovinmatveevnovikov1976nonlinear}. The stationary hierarchy mechanism is already in \citet[\S2]{novikov1974periodic}.',refs=['dubrovinmatveevnovikov1976nonlinear','novikov1974periodic'],cls='A',reconstruction=r'The distinction between variational critical-point equations and Hamiltonian time evolution repairs an abbreviated phrase.')
item(343,'P000567, property10','theorem','Variational derivative of quasimomentum',r'\(\delta p(E)/\delta u(x)=-1/(2\chi_R(x,E))\).',r'For real smooth periodic \(u\), a spectral parameter in a band interior, and a fixed local branch of quasimomentum, its first variation under periodic \(v\) is \(D p(u)[v]=-\tfrac12\int_0^T v(x)/\chi_R(x,E)\,dx\). The local choice removes the additive \(2\pi\) ambiguity; analytic continuation requires consistent sheet choice.',r'\citet[Chapter2, Eq.~(2.1.17)]{dubrovinmatveevnovikov1976nonlinear} gives the same formula, referring to Dubrovin\textquotesingle s1975 inverse-problem papers. Seminar circulation is established by this September1974 page.',refs=['dubrovinmatveevnovikov1976nonlinear'],cls='A')
item(343,'P000567, property11','construction','Expressing the logarithmic derivative through monodromy',r'\(\chi=\sqrt{1-\tau^2}/\alpha_{21}+\tfrac i2(\alpha_{11}-\alpha_{22})/\alpha_{21}\).',r'Use the coefficient-basis convention \(T=\begin{pmatrix}c(T)&c^{\prime}(T)\\s(T)&s^{\prime}(T)\end{pmatrix}\), so \(\alpha_{21}=s(T)\). Solving the Bloch eigenvector equation gives the displayed expression, with the sign of the square root selecting the multiplier. Where \(s(T)=0\), interpret it meromorphically or use the other chart.',r'The two basis conventions are distinguished in \citet[Chapter2, Eq.~(2.1.19)]{dubrovinmatveevnovikov1976nonlinear}. Changing to the usual fundamental-state matrix interchanges the off-diagonal indices.',refs=['dubrovinmatveevnovikov1976nonlinear'],reconstruction=r'The manuscript leaves its matrix-entry convention implicit. The transposed coefficient convention is selected so the written alpha21 formula is valid.')
item(343,'P000567-P000568, property12','construction','The finite-gap polynomial divisor representation',r'\(R(E)=\prod_{j=1}^{2N+1}(E-E_j)\), \(P(E,x)=\prod_{j=1}^{N}(E-\gamma_j(x))\), \(\chi=\sqrt R/P-\tfrac i2P_x/P\).',r'For a nonsingular real finite-gap Schr\"odinger potential with \(N\) open gaps, choose the branch of \(\sqrt R\) behaving as \(E^{N+1/2}\), and the monic degree-\(N\) divisor polynomial \(P\). Then the logarithmic derivative has the displayed meromorphic expression on \(w^2=R(E)\). Its zeros and poles must satisfy the Schr\"odinger compatibility identity, so an arbitrary pair of polynomials does not suffice.',r'\citet[Chapter2, \S\S2--3]{dubrovinmatveevnovikov1976nonlinear}; the relation between stationary operators and the spectral polynomial appears in \citet[\S2]{novikov1974periodic}.',refs=['dubrovinmatveevnovikov1976nonlinear','novikov1974periodic'],cls='A',development='annotated')
item(343,'P000568, Gelfand problem','problem','Entire functions of order one in place of finite-gap polynomials',r'\ru{Пусть R и P --- целые ф-и 1-го пор. роста. Тогда им соотв. потенциалы u(x). Какие?} The next line says that periodicity is not required.',r'The strongest literal content is a request to identify potentials associated with an entire-function extension of the preceding \(R,P\) expression. The page supplies no normalization, admissibility, reality, zero-divisor conditions or precise meaning of the growth variable. Consequently there is no uniquely determined global inverse problem to classify as solved or open.',r'Finite-gap inverse data are developed in \citet[Chapter2, \S3]{dubrovinmatveevnovikov1976nonlinear}. The verification appendix proves an explicit local compatibility criterion and a normalization obstruction for the notebook ansatz; this is an editorial audit, not a historical solution of an unspecified global question.',refs=['dubrovinmatveevnovikov1976nonlinear'],cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',development='annotated',confidence='medium',status='As of November2026, the intended exact entire-function classification remains unidentifiable from this paragraph. The local compatibility issue can be checked, but no residual research conjecture is manufactured.')
item(343,'P000568, Dubrovin theorem','theorem','Bloch function on the hyperelliptic curve',r'Dubrovin states that \(\Psi(x,x_0,E)\) is single-valued on \(\Gamma_N\), meromorphic away from infinity, with \(N\) zeros above \(\gamma_i(x)\) and \(N\) poles above \(\gamma_i(x_0)\).',r'For nonsingular finite-gap spectral data with a nonspecial divisor of degree \(N\), the normalized Baker--Akhiezer function is single-valued and meromorphic on the curve minus its point at infinity; its polar divisor is bounded by the initial divisor and its zero divisor by the moving divisor, with \(N\) points counting multiplicity before cancellation. At \(x=x_0\) the function is1, so coincident zero and pole divisors cancel. At infinity it has the prescribed exponential singularity.',r'\citet[Chapter2, \S1, p.~77 and \S3]{dubrovinmatveevnovikov1976nonlinear} supplies the divisor description and theta-function inverse construction. The notebook proves circulation by23September1974; the relevant announcements appeared1974--1975.',refs=['dubrovinmatveevnovikov1976nonlinear'],cls='A',speaker='B. A. Dubrovin',reconstruction=r'Multiplicity, divisor cancellation, nonspeciality and the exponential behavior at infinity are made explicit; the literal count fails at the normalization point.',literal='correct with missing hypotheses')
P.append(dict(id='GP-1974-10',title='Finite-gap spectra and stationary KdV characterization',statement=r'For real smooth periodic potentials, characterize when the whole-line Schr\"odinger spectrum has only finitely many open bounded gaps, and relate this to stationary equations of the KdV hierarchy.',occurrences=['1973-326.15','1974-343.2'],status=r'As of November2026, solved in the stationary-KdV and finite-gap theory developed in1974--1976; see \citet[\S2]{novikov1974periodic} and \citet[Chapter2, \S2]{dubrovinmatveevnovikov1976nonlinear}. This is distinct from the supplementary-data inverse problem GP-1973-51 and the density problem GP-1973-52.',status_date='2026-11',refs=['novikov1974periodic','dubrovinmatveevnovikov1976nonlinear']))
corr('P000566','Periodicity in the opening display',r'\(u(x+T)=u(y)\).',r'\(u(x+T)=u(x)\).',r'The handwritten right side clearly has y. The next page explicitly writes u(x+T)=u(x); the discussion requires a periodic potential.')
corr('P000566','Extrema after gaps close',r'Maxima and minima are eventually equal to1.',r'Maxima are at+1 and minima at−1; equivalently the absolute extrema are1.',r'The corrected scan sketch oscillates between two levels. Infinite periodic/antiperiodic eigenvalues remain; closing gaps does not make the discriminant constant.')
corr('P000567','Scope of the opening radical',r'A radical drawn above the numerator of \((\tau^2-1)/\prod(E-E_j)\).',r'Interpret as \(\sqrt{(\tau^2-1)/\prod(E-E_j)}\), with the entire quotient under the radical.',r'The overbar ends over the numerator but the left radical stroke descends beside the denominator. Only the full-quotient reading is single-valued at each simple band endpoint. Mathematical scope is inferred, not visually certain.',typ='ambiguity')
corr('P000567','Allowed and forbidden zones sentence',r'Allowed and forbidden zones---where \(|\lambda|=1\).',r'Allowed zones have \(|\lambda|=1\); in open forbidden intervals the multipliers are real reciprocal and have moduli different from1.',r'The scan has the same abbreviated sentence; P000566 gives the correct alternative explicitly. Faithful shorthand cannot be read as a criterion for both kinds of interval.')
save()

# Record 346.
talk(346,'1974-10-07','A. G. Kushnirenko','P000571-P000573','Local Milnor numbers from Newton polyhedra',r'The dated pageP000572 defines the multiplicity of an isolated critical point and asks how to recover it from Taylor coefficients. Kushnirenko gives the Newton lower bound and its generic equality in two and three dimensions, then onP000573 states face nondegeneracy through a finite-codimension monomial-ring quotient. The argument invokes Hochster\textquotesingle s Cohen--Macaulay theorem. The paper announcing these results was received on30September1974, a week before the recorded lecture, and appeared in1975.')
item(346,'P000572, opening and margin','definition','Milnor number as local gradient multiplicity',r'For an analytic germ without constant or linear terms, \(\mu(f)\) is the multiplicity of the zero solution of \(\partial f/\partial z_i=0\), also described as the maximum number of solutions to \(\partial f/\partial z_i=\varepsilon_i\) for small \(\varepsilon\).',r'Let \(f\in\mathbb C\{z_1,\ldots,z_n\}\) have an isolated critical point at0. Then \(\mu(f)=\dim_{\mathbb C}\mathbb C\{z\}/(f_{z_1},\ldots,f_{z_n})\). For a sufficiently small isolating neighborhood and a sufficiently small generic regular value \(\varepsilon\), the gradient equation has exactly \(\mu(f)\) simple solutions there. Nongeneric perturbations require multiplicities.',r'This local-algebra invariant is part of the established singularity theory preceding the talk. \citet[\S1]{kushnirenko1975newton} fixes the same definition; its use here is expository, while the Newton formula is the new result.',refs=['kushnirenko1975newton'],literal='correct with missing hypotheses',reconstruction=r'Isolation, the local neighborhood, genericity and the distinction between distinct and multiple roots are made explicit.')
item(346,'P000572, task and Newton diagrams','construction','The Newton boundary and its alternating volume number',r'\ru{Задача: вычислить} \(\mu(f)\) from Taylor coefficients. The lower Newton polygon gives \(\nu=2S-a-b+1\); in dimension3 the formula is \(6V-2(S_{12}+S_{13}+S_{23})+(L_1+L_2+L_3)-1\).',r'For a convenient germ, meaning its support meets every coordinate axis, take the compact faces of \(\operatorname{conv}(\operatorname{supp}f+\mathbb R_{\ge0}^n)\) and the region \(\Gamma_-\) swept out between them and0. If \(V_j\) is the sum of ordinary \(j\)-dimensional volumes of intersections of \(\Gamma_-\) with coordinate \(j\)-planes and \(V_0=1\), then \(\nu(f)=\sum_{j=0}^n(-1)^{n-j}j!V_j\). Its cases \(n=2,3\) are exactly the written formulas.',r'The definition and formulas are in \citet[\S\S2--3]{kushnirenko1975newton}; received30September1974, published1975. The arbitrary-dimensional expression is also the organizing definition in the full1976 paper, \citet{kouchnirenko1976polyedres}.',refs=['kushnirenko1975newton','kouchnirenko1976polyedres'],cls='A',problem='GP-1974-12',reconstruction=r'Convenience and the meaning of each coordinate-section volume are supplied. The general sum packages the two formulas actually recorded; it is not attributed as an additional notebook display.')
item(346,'P000572, two theorems','theorem','Kushnirenko lower bound and equality under nondegeneracy',r'Both dimension2 and dimension3 displays state \(\mu(f)\ge\nu(f)\), with equality under nondegeneracy; the condition holds almost always.',r'For a convenient holomorphic germ with an isolated critical point, \(\mu(f)\ge\nu(f)\). If for every compact face \(\Delta\) the face polynomial \(f_\Delta\) has no critical point in \((\mathbb C^*)^n\), then equality holds. At a fixed convenient Newton boundary, the exceptional face coefficients lie in a proper algebraic subset, so equality holds generically. Equality for every degenerate germ is not claimed.',r'Exact match with \citet[TheoremI(i)--(iii)]{kushnirenko1975newton}. The1975 announcement gives the statement; \citet{kouchnirenko1976polyedres}, published1976, supplies the extended proof. The recorded talk establishes circulation by7October1974 and the received date establishes the announcement existed a week earlier.',refs=['kushnirenko1975newton','kouchnirenko1976polyedres'],cls='A',problem='GP-1974-12')
item(346,'P000572, edge discriminant','claim','Nondegeneracy of an edge polynomial',r'The illustration gives \(\beta^2\ne4\alpha\gamma\), and the text calls for the discriminant of each edge to be nonzero, because an edge is essentially a one-variable polynomial.',r'After removing a monomial and using a primitive lattice coordinate along an edge, its face polynomial becomes a one-variable polynomial. Nonzero roots must be simple. For a quadratic edge polynomial with nonzero endpoint coefficients \(\alpha,\gamma\), this is \(\beta^2-4\alpha\gamma\ne0\). In two variables this test must be applied to every compact edge; in higher dimensions it does not replace the conditions on higher-dimensional faces.',r'This is the planar face test for the nondegeneracy condition in \citet[\S8]{kushnirenko1975newton}. The precise quadratic discriminant follows by elementary differentiation; it is an explanatory specialization of the new general theorem.',refs=['kushnirenko1975newton'],cls='A',literal='correct with missing hypotheses',reconstruction=r'The lattice coordinate, removal of monomial factors and nonzero endpoint coefficients are explicit safeguards against an overbroad discriminant test.')
item(346,'P000573, first formula','definition','Face nondegeneracy as a finite-codimension ideal',r'For the cone \(P(\Delta)\) over a face, \(\dim_{\mathbb C}\mathbb C[P(\Delta)]/(z_i\partial f_\Delta/\partial z_i)<\infty\) is written.',r'For a compact face \(\Delta\) disjoint from0, let \(P(\Delta)=\operatorname{cone}(\Delta)\cap\mathbb Z_{\ge0}^n\). In the semigroup ring \(\mathbb C[P(\Delta)]\), require the ideal generated by all logarithmic derivatives \(z_i\partial f_\Delta/\partial z_i\) to have finite vector-space codimension. Requiring this for every face is the algebraic nondegeneracy formulation used in the announcement.',r'The notation and condition agree exactly with \citet[\S8]{kushnirenko1975newton}. They connect the geometric volume formula to a finite-dimensional quotient; no global polynomial gradient quotient is being taken at this stage.',refs=['kushnirenko1975newton'],cls='A',literal='correct with missing hypotheses')
item(346,'P000573, proof sentence','method','Cohen--Macaulay semigroup rings in the proof',r'The proof is said to use commutative algebra and Hochster\textquotesingle s assertion that \(\mathbb C[P(\Delta)]\) is Cohen--Macaulay.',r'For a finitely generated saturated affine semigroup \(P\), its semigroup algebra over a field is Cohen--Macaulay. The lattice points of the rational polyhedral cone over \(\Delta\) satisfy these hypotheses. This property supplies regular-sequence and Hilbert-series control when the face-gradient ideal has finite codimension.',r'Hochster\textquotesingle s theorem was published in September1972, before the lecture: \citet[main theorem]{hochster1972invariants}. Its use in this Newton-polyhedron argument is reported by the notebook and developed in \citet{kouchnirenko1976polyedres}.',refs=['hochster1972invariants','kouchnirenko1976polyedres'],cls='E',literal='correct with missing hypotheses',verification='indirect',reconstruction=r'Saturation and finite generation are essential. An arbitrary ring generated by an arbitrary selection of monomials need not be Cohen--Macaulay.')
P.append(dict(id='GP-1974-12',title='Computing local Milnor numbers from Newton data',statement=r'For a holomorphic germ with an isolated critical point and a fixed convenient Newton boundary, find a lower bound for the Milnor number in terms of that boundary, and state coefficient conditions under which the bound is attained.',occurrences=['1974-346.2','1974-346.3'],status=r'As of November2026, resolved by the Newton-number inequality and equality for face-nondegenerate germs. This does not say that the Newton boundary alone determines the Milnor number of every degenerate germ. \citet[TheoremI]{kushnirenko1975newton}, received30September1974 and published1975; full treatment in \citet{kouchnirenko1976polyedres}.',status_date='2026-11',refs=['kushnirenko1975newton','kouchnirenko1976polyedres']))
save()

# Record 347: one precise paragraph, not the following lattice-gauge discussion.
talk(347,'1974-10-07','V. I. Arnold','P000571-P000576','A polynomial residue-sum identity',r'Arnold\textquotesingle s contribution is the single paragraph near the top ofP000573, between Kushnirenko\textquotesingle s proof remark and Polyakov\textquotesingle s lattice-field discussion. It gives a sum of polynomial values divided by the Jacobian over \(n^2\) intersection points. The written degree bound is \(n-4\), which is a valid weaker bound under the standard hypotheses; it is not silently changed to the sharp classical bound.')
item(347,'P000573, Arnold paragraph','theorem','Euler--Jacobi vanishing of the total residue',r'For two degree-\(n\) polynomials \(P_n,Q_n\), the notes give \(\sum_{P_n=Q_n=0} R_{n-4}(x,y)/\det\bigl(\partial(P_n,Q_n)/\partial(x,y)\bigr)=0\), summing over all \(n^2\) zeros.',r'Let \(P,Q\in\mathbb C[x,y]\) have degree \(n\ge4\), with leading homogeneous parts having no common nonzero zero, and suppose their \(n^2\) affine intersection points are simple. Then for every polynomial \(R\) of degree at most \(2n-3\), \(\sum_{P(a)=Q(a)=0}R(a)/(P_xQ_y-P_yQ_x)(a)=0\). In particular the notebook\textquotesingle s degree at most \(n-4\) satisfies the theorem.',r'This is the classical Euler--Jacobi formula, not a newly posed residue problem. \citet[Corollary, p.~237]{khovanskii1978eulerjacobi} states the general degree bound and explicitly treats it as classical, while proving a Newton-polyhedron generalization suggested by Arnold. The1978 result is a later development of the theme, not evidence that this1974 formula was new.',refs=['khovanskii1978eulerjacobi'],cls='E',literal='correct with missing hypotheses',reconstruction=r'Transversality, absence of intersections at infinity and n>=4 are explicit. The stronger2n-3 bound is a literature comparison; n-4 is the legible original reading, not an OCR error.',match='exact',development='annotated')
corr('P000573','Arnold numerator and stated degree bound',r'\(R_{n-4}\), degree at most \(n-4\).',r'Retain \(n-4\) as the source reading; annotate that the classical theorem permits degree at most \(2n-3\), assuming simple affine intersections and no intersections at infinity.',r'The scan clearly shows n-4 both in the subscript and explanatory line. Its weaker bound is not mathematically false. This row prevents an unjustified editorial replacement with the sharper familiar formula.',typ='ambiguity')
save()

# Record 349: global, rather than local, Newton data.
talk(349,'1974-10-21','A. G. Kushnirenko','P000578-P000580','Global critical-point counts and Newton polyhedra',r'The upper portion ofP000579 treats all isolated critical points of a polynomial on \(\mathbb C^n\). Its polytope is the convex hull of0 and the support, rather than the local lower Newton boundary. The total Milnor number is bounded above by the associated Newton number, with equality under nondegeneracy at infinity. The normalized-gradient degree explains the total multiplicity; Hochster\textquotesingle s theorem and Mumford\textquotesingle s toric viewpoint are named as tools.')
item(349,'P000579, polynomial and counting question','question','The total Milnor number of a polynomial',r'For \(P:\mathbb C^n\to\mathbb C\), all critical points are assumed isolated. The question is how to count them with multiplicities.',r'When the gradient ideal has finite colength, the finite sum of local critical-point multiplicities is \(\mu_{\mathrm{tot}}(P)=\dim_{\mathbb C}\mathbb C[z_1,\ldots,z_n]/(P_{z_1},\ldots,P_{z_n})=\sum_{a\in\operatorname{Crit}(P)}\mu_a(P)\). The question is to bound and generically compute this number from the support of \(P\).',r'The equality with the sum of local algebras is \citet[\S\S4--5]{kushnirenko1975newton}; the ensuing Newton bound is its TheoremII. The paper was received30September1974 and published1975; the notebook records the global discussion on21October1974.',refs=['kushnirenko1975newton'],cls='A',literal='correct',problem='GP-1974-13')
item(349,'P000579, convex hull and two inequalities','theorem','The Newton upper bound and equality at infinity',r'Take the convex hull of0 and the exponents with nonzero coefficients. In two dimensions the count is at most \(2S-a-b+1\), with equality under nondegeneracy.',r'Let \(P\) be convenient, so its support meets every coordinate axis. For \(\Delta_\infty=\operatorname{conv}(\{0\}\cup\operatorname{supp}P)\), define \(\nu_\infty\) by the same alternating sum of coordinate-section volumes as in record346. Then \(\sum\mu_a(P)\le\nu_\infty\). Equality holds if every face at infinity is nondegenerate in the logarithmic-derivative sense; in that case the critical locus is finite. In dimension2 this is \(2S-a-b+1\).',r'Exact match with \citet[TheoremII(i)--(iii)]{kushnirenko1975newton}, including genericity at fixed support; \citet{kouchnirenko1976polyedres} gives the full treatment. This upper bound and the local lower bound concern different Newton regions and are compatible.',refs=['kushnirenko1975newton','kouchnirenko1976polyedres'],cls='A',literal='correct with missing hypotheses',problem='GP-1974-13',reconstruction=r'Convenience and nondegeneracy on every relevant face at infinity are supplied; arbitrary support or a single tested face does not justify the formula.')
item(349,'P000579, degree-of-map argument','method','Global multiplicity as the degree of the normalized gradient',r'The map on \(|z|=R\) sends \(z\) to \((P_{z_1},\ldots,P_{z_n})/|\operatorname{grad}P|\); the sum of Milnor numbers equals its degree.',r'Choose \(R\) so every isolated critical point lies strictly inside the ball and the gradient is nonzero on its boundary. With complex orientations, \(\deg(\nabla P/\|\nabla P\|:S_R^{2n-1}\to S^{2n-1})=\sum_a\mu_a(P)\). This is additivity of the degree of a holomorphic map with isolated zeros. It does not require the gradient to be a proper map of all of \(\mathbb C^n\).',r'The local multiplicity/degree interpretation belongs to the established theory of isolated holomorphic singularities, as in \citet[\S7]{milnor1968singular}. Kushnirenko\textquotesingle s1975 global algebraic count provides the exact support-dependent invariant. The notebook uses the degree principle as a proof idea, not as a new independent theorem.',refs=['milnor1968singular','kushnirenko1975newton'],cls='E',literal='correct with missing hypotheses',verification='indirect')
item(349,'P000579, Hochster sentence','theorem','Normal cone semigroup algebras are Cohen--Macaulay',r'The ring of monomials whose exponents lie in a cone is said to be Cohen--Macaulay; Melvin Hochster is named at the head of the page.',r'For a rational polyhedral cone \(\sigma\subset\mathbb R_{\ge0}^n\), the saturated finitely generated semigroup \(\sigma\cap\mathbb Z^n\) defines a normal affine semigroup ring \(\mathbb C[\sigma\cap\mathbb Z^n]\), and this ring is Cohen--Macaulay. Saturation is a hypothesis, not a consequence for an arbitrary selected set of monomial generators.',r'\citet[main theorem]{hochster1972invariants}, publishedSeptember1972. This is the same proof ingredient already mentioned in1974-346.6; the second occurrence is retained because the global counting argument invokes it explicitly.',refs=['hochster1972invariants'],cls='E',literal='correct with missing hypotheses',verification='indirect')
item(349,'P000579, Mumford line','remark','Toric compactifications as the geometric interpretation',r'The final line before Polyakov says only \ru{Мамфорд --- торич. вложения}.',r'The identifiable method is to treat the cone monomial rings as affine charts of toric varieties and use a toric compactification adapted to the Newton polytope. No particular fan, compactification theorem or intersection formula is specified on this page.',r'The connection is consistent with the toric proof language of the Newton-polyhedron literature, including \citet[proof of the theorem]{khovanskii1978eulerjacobi}. That is a thematic comparison only; this isolated name does not identify a distinct theorem of Mumford or justify a new open-problem entry.',refs=['khovanskii1978eulerjacobi'],cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',confidence='medium',status='As of November2026, the toric-geometric method is identifiable, but the exact Mumford result intended by this isolated line is not. No mathematical question is stated.')
P.append(dict(id='GP-1974-13',title='Counting all isolated critical points from the Newton polytope',statement=r'For a convenient complex polynomial, bound the sum of Milnor numbers of its isolated critical points by the convex hull of0 and its support, and characterize a generic class attaining the bound.',occurrences=['1974-349.1','1974-349.2'],status=r'As of November2026, resolved by the global Newton-number theorem: the count is at most the alternating coordinate-volume number and equals it under nondegeneracy at infinity. See \citet[TheoremII]{kushnirenko1975newton}. The general mixed-volume root-counting theorem is related but is not substituted for this gradient-specific assertion.',status_date='2026-11',refs=['kushnirenko1975newton','kouchnirenko1976polyedres']))
save()

# Record 345: catalogue heading 30 September; detailed discussion under 7 October.
talk(345,'1974-09-30','A. M. Polyakov','P000568-P000573','Lattice gauge fields, Wilson loops, and thermodynamic phases',r'P000569 names Polyakov and a difference analogue of Yang--Mills theory under30September. The substantive formulas occur onP000573--P000574, after the7October heading and Arnold\textquotesingle s intervention. The catalogue date is preserved, while this manuscript displacement is recorded. Compact-group link variables and plaquette products lead to Gibbs integrals and loop observables. Sinai then specializes to an angular \(U(1)\) model. Its Bessel partition function must not be transferred unchanged to \(SU(2)\), and the final area/perimeter remark does not specify a complete phase-transition theorem.')
item(345,'P000573, Polyakov opening and plaquette sketch','definition','Compact-group link variables and plaquette holonomy',r'Oriented lattice edges carry \(B_{\tau,\alpha}\in SU(2)\), or another compact group. The oriented square has \(F_{\tau,\alpha\beta}=B_{\tau,\alpha}B_{\tau+a_\alpha,\beta}B_{\tau+a_\beta,\alpha}^{-1}B_{\tau,\beta}^{-1}\).',r'On a finite square lattice, assign \(U_{xy}\in G\) to each oriented link, with \(U_{yx}=U_{xy}^{-1}\). The ordered product around a plaquette is its holonomy. Under vertex gauge transformations \(U_{xy}\mapsto h_xU_{xy}h_y^{-1}\), that product is conjugated at its basepoint, so a character or a real class function of it is gauge invariant.',r'The construction is in \citet[\SIII, especially the non-Abelian extension]{wilson1974confinement}. Wilson\textquotesingle s manuscript was received12June1974 and the CLNS-262 preprint is catalogued February1974; publication was15October1974. Thus it was already circulating before either possible notebook meeting date.',refs=['wilson1974confinement'],cls='E',literal='correct')
item(345,'P000573, energy and partition integral; P000574, Gibbs density','definition','The finite-volume lattice Gibbs measure',r'\(E[B]=\sum\chi(F)\), \(Z=\int\prod dB\,e^{-E/T}\), and \(p(B)=Z^{-1}e^{-\beta E(B)}\), with \(\chi\) described as trace.',r'For compact \(G\), normalized Haar measure on each unoriented link and a real bounded plaquette class function \(V\), define \(E(U)=\sum_pV(U_p)\), \(Z_\Lambda(\beta)=\int e^{-\beta E(U)}\prod_edU_e\), and the probability measure with this normalized density. For \(SU(2)\) the fundamental trace is real; for general compact groups one must use a real character combination such as \(\operatorname{Re}\chi\). The sign and normalization of \(V\) must be fixed before comparing coupling constants.',r'\citet[\SIII.B]{wilson1974confinement} gives the finite-volume Euclidean lattice integral. The notebook\textquotesingle s positive-trace energy is a legitimate sign convention but differs from the common ferromagnetic action \(-\operatorname{Re}\operatorname{tr}U_p\).',refs=['wilson1974confinement'],cls='E',literal='correct with missing hypotheses')
item(345,'P000573, correlation display; P000574, contour average','definition','The Wilson loop as a gauge-invariant correlation',r'\(\Pi(C)=Z^{-1}\int\chi(\prod_C B)e^{-\beta E(B)}\prod dB\); \(C\) is a closed contour.',r'For an oriented closed lattice path \(C\), use the path-ordered product of link variables, replacing a reversed edge by its inverse. Its character is independent of the chosen starting vertex, and its Gibbs expectation is gauge invariant. A normalized trace divides by the representation dimension; the notebook uses the unnormalized trace.',r'\citet[Eq.~(3.13) and \SII]{wilson1974confinement} gives this loop observable and its physical interpretation. The recorded expression is an explicit lattice Wilson loop, not an arbitrary two-point correlation function.',refs=['wilson1974confinement'],cls='E',literal='correct with missing hypotheses')
item(345,'P000573, planar exact-solvability statement','method','Exact integration in two dimensions',r'\ru{Плоская зад. решается точно} follows the finite \(N\times N\) lattice definition.',r'For a simply connected finite planar lattice with open boundary and a central plaquette weight \(w:G\to\mathbb R_{>0}\), a spanning-tree gauge choice reduces the partition integral to independent plaquette integrals. If \(w=\sum_\rho a_\rho\chi_\rho\), the disk amplitude with boundary holonomy \(g\) is \(\sum_\rho d_\rho(a_\rho/d_\rho)^A\chi_\rho(g)\), where \(A\) is the number of plaquettes. Integrating the boundary gives \(Z=a_{\mathrm{triv}}^A\). Periodic boundary identifications impose additional global constraints.',r'The later exact character-expansion formulation is explicitly derived in \citet[AppendixA.1, Eqs.~(A.6)--(A.11)]{hirasawa2020complex}. This verifies the statement in a specified planar setting; it is not evidence that the2020 paper was the first solution, or that the notebook\textquotesingle s unspecified boundary conditions are immaterial.',refs=['hirasawa2020complex','wilson1974confinement'],cls='B',literal='correct with missing hypotheses',match='partial',reconstruction=r'The region, boundary treatment, central weight and character normalization are supplied to make the phrase exactly solvable precise.')
item(345,'P000573, two spin-energy displays','construction','Coupling group-valued spins to a lattice connection',r'The spin energy \(\sum\chi(g_\tau^{-1}g_{\tau+a_\alpha})\) is followed by \(\sum\chi(g_\tau^{-1}g_{\tau+a_\alpha}B_{\tau,\alpha})+E[B]\).',r'Group-valued spins with a global symmetry can be coupled to link transport to make the interaction locally gauge invariant. For example, with \(g_x\mapsto g_xh_x^{-1}\) and a reverse transporter \(B_{xy}\mapsto h_yB_{xy}h_x^{-1}\), the factor \(\chi(g_x^{-1}g_yB_{xy})\) is invariant. Equivalently one can use forward links and the conventional \(\chi(g_x^{-1}U_{xy}g_y)\), with the corresponding left action on spins. Mixing these conventions destroys invariance.',r'Gauge-invariant matter coupling is already present in \citet[\SIII.A]{wilson1974confinement}; \citet{baliandrouffeitzykson1974gauge} develops the coupled group-spin model, received3June1974 and published15November1974. The notebook does not specify its transport convention, so the displayed ordering has only a partial exact match.',refs=['wilson1974confinement','baliandrouffeitzykson1974gauge'],cls='B',literal='correct with missing hypotheses',match='partial',verification='read the result',reconstruction=r'The transformation laws are an explicit editorial consistency check. The two energy displays are retained as one gauging construction rather than treated as two unrelated models.')
item(345,'P000573, field theory and statistical mechanics','remark','Euclidean continuation and transfer matrices',r'Field theory is identified with statistical mechanics in Euclidean \(\mathbb R^n\); the parenthesis says \ru{преобр. Фурье по времени}.',r'The relevant formal passage from Lorentzian quantum dynamics to Euclidean Gibbs weights is continuation to imaginary time. For a lattice theory, a suitable positive transfer operator relates Euclidean correlation functions to a quantum Hamiltonian. An ordinary Fourier transform in real time alone does not make the Minkowski action into a positive Euclidean Gibbs energy.',r'\citet[\S I and \SIII.B]{wilson1974confinement} explicitly uses imaginary time and the transfer-matrix construction. The notebook\textquotesingle s Fourier-transform wording is an imprecise shorthand requiring correction; no general constructive-equivalence theorem is stated.',refs=['wilson1974confinement'],cls='E',literal='false as written',development='annotated')
item(345,'P000573, Sinai partition function; P000574, angular specialization','claim','When the Bessel partition function is valid',r'Sinai writes \(\log Z(\beta,V)=V\log I_0(\beta)\). The next page has \(B=e^{iA}\) and \(E=\sum\cos(\operatorname{curl}A)\).',r'For the planar \(U(1)\) model with normalized link-angle measure, open boundary, and \(A\) plaquettes, \(Z=I_0(\beta)^A\), where \(I_m(\beta)=(2\pi)^{-1}\int_{-\pi}^{\pi}e^{\beta\cos\theta}\cos(m\theta)\,d\theta\). The notebook\textquotesingle s opposite action sign gives the same \(I_0\). This is not the \(SU(2)\) formula: for fundamental trace and weight \(e^{\beta\operatorname{tr}U}\), a normalized one-plaquette integral is \(I_1(2\beta)/\beta\). If \(V\) counts sites rather than plaquettes, the written equality is only asymptotic.',r'The general exact integration is verified in \citet[AppendixA.1 and A.3]{hirasawa2020complex}; the elementary Haar integrations are written out in the verification appendix. These distinguish an Abelian specialization from the preceding \(SU(2)\) example. No specific publication by Sinai carrying this exact formula was identified.',refs=['hirasawa2020complex','wilson1974confinement'],cls='B',speaker='Ya. G. Sinai',literal='correct with missing hypotheses',match='partial',development='annotated',reconstruction=r'U(1), normalized Haar measure, open boundary and plaquette count are required. The SU(2) comparison is editorial and not attributed to Sinai.')
item(345,'P000574, thermodynamic limit','theorem','Boundary independence of the pressure',r'\(\lim_{V\to\infty}V^{-1}\log Z(\beta,V)=f(\beta)\) is asserted to be independent of boundary conditions.',r'For translation-invariant bounded finite-range interactions on compact lattice variables, with normalized product a priori measure, pressure exists along van Hove boxes and is unchanged by boundary conditions whose change affects only a boundary layer of bounded energy per interaction. Indeed boundary choices change \(\log Z\) by at most a constant times the number of boundary interactions, which is \(o(V)\). This is a statement about pressure, not uniqueness of the infinite-volume Gibbs state.',r'The thermodynamic-limit framework precedes the talk; \citet[Theorem1]{ruelle1967variational} treats lattice pressure for summable interactions in the finite-state setting. The bounded compact-variable formulation here is its standard boundary-estimate extension, not an exact quotation of that theorem. The explicit planar model also has pressure \(\log I_0(\beta)\).',refs=['ruelle1967variational','hirasawa2020complex'],cls='E',speaker='Ya. G. Sinai',literal='correct with missing hypotheses',match='partial',reconstruction=r'The shape of the limit, bounded finite-range interactions and ordinary boundary perturbations are supplied. Boundary independence alone does not rule out phase coexistence.')
item(345,'P000574, phase-transition sentence','definition','Nonanalyticity in the infinite-volume limit',r'Singularities of \(f(\beta)\) are called phase transitions, accompanied heuristically by a change in typical configurations.',r'A finite-volume partition integral with bounded energy is entire in complex \(\beta\) and positive for real \(\beta\), so its real logarithm is locally analytic. Thermodynamic singularities can arise only after the infinite-volume limit. Nonanalytic pressure is a thermodynamic phase-transition criterion, while a full classification of Gibbs phases also involves states and order parameters. In the written planar \(U(1)\) model, \(\log I_0(\beta)\) is analytic at every finite real \(\beta\).',r'The distinction between finite volume and thermodynamic phases is classical; compare \citet[\S I]{wilson1974confinement} and \citet{ruelle1967variational}. The analytic \(I_0\) formula prevents reading this paragraph as a proof of a finite-temperature transition in that particular two-dimensional example.',refs=['wilson1974confinement','ruelle1967variational'],cls='E',speaker='Ya. G. Sinai',literal='correct with missing hypotheses',match='partial',development='annotated')
item(345,'P000574, final area/length comparison','remark','Area and perimeter laws require a specified model',r'The last two lines say that in one phase the correlation is proportional to area and in another to contour length.',r'The intended diagnostic is \(-\log|\langle W(C)\rangle|\) growing proportionally to the area enclosed by a large loop or to its perimeter. The expectation itself decays exponentially. Dimension, gauge group, matter content, action, family of loops and limiting regime must be specified before the phrase becomes a theorem. In the planar pure \(U(1)\) model with positive \(\beta\), \(|\langle W(C)\rangle|=(I_1(\beta)/I_0(\beta))^{A(C)}\) for a simple loop, so it has an area law at every finite \(\beta>0\).',r'\citet[\S II and \S IV]{wilson1974confinement} supplies the area/perimeter criterion and a strong-coupling analysis, but it does not turn the notebook\textquotesingle s unspecified assertion into a universal two-phase theorem. The exact planar conclusion follows from independent plaquette integration; no modern Yang--Mills mass-gap problem is silently substituted.',refs=['wilson1974confinement','hirasawa2020complex'],cls='F',speaker='Ya. G. Sinai',literal='not determinable',match='thematic only',verification='unresolved lead',development='annotated',confidence='medium',status='As of November2026, the physical diagnostic is identifiable, but no definite residual conjecture is specified here. The adjacent two-dimensional Abelian example is exactly solvable and has no finite-coupling area/perimeter phase transition.')
corr('P000573-P000574','Date and passage boundary of the lattice-gauge discussion',r'Catalogue record345:30September1974, pagesP000568--P000573.',r'Keep the catalogue date, but locate the detailed formulas onP000573--P000574 under the7October1974 manuscript heading; only the topic announcement is onP000569 under30September.',r'Source headings and speaker transitions are visible in the scans. The final pressure and phase paragraph onP000574 continues Sinai\textquotesingle s formula at the bottom ofP000573.',typ='provenance')
corr('P000573','Parenthetical operation in time',r'Fourier transform in time.',r'Imaginary-time continuation, with a transfer-matrix interpretation when justified.',r'The Russian handwriting says Fourier. Wilson1974 explicitly describes imaginary rather than real times; a Fourier transform does not perform Wick rotation. This is a faithful conceptual shorthand, not a translation mistake.')
corr('P000573-P000574','Scope of the I0 partition formula',r'\(\log Z=V\log I_0(\beta)\) immediately following an \(SU(2)\) example.',r'For normalized Haar measure this formula requires the subsequent \(U(1)\) angular specialization, an open planar region, and \(V\) equal to the number of plaquettes. The fundamental-trace \(SU(2)\) factor is \(I_1(2\beta)/\beta\).',r'The next page writes B=e^{iA} and a scalar cosine of the discrete curl. Direct one-plaquette Haar integration distinguishes the two groups; periodic boundaries impose an additional global constraint.')
corr('P000574','Area and contour-length comparison',r'The correlation is proportional to area in one phase and length in another.',r'Interpret area/perimeter growth for \(-\log|\langle W(C)\rangle|\); specify the model before asserting two phases.',r'Wilson1974, SectionsII andIV, uses exponential suppression of the loop expectation. The finite-beta planar U(1) example has an area law throughout, so the literal unqualified phase claim is not justified.')
save()

# Record 350.
talk(350,'1974-10-21','A. M. Polyakov','P000578-P000582','Yang--Mills connections, curvature, and characteristic forms',r'The lower portion ofP000579 returns from the lattice model to the continuum action. Polyakov identifies the gauge potential with connection coefficients, the field strength with curvature, and a quadratic curvature expression with a Pontryagin form. This is an expository geometric dictionary. The handwritten action has misplaced indices and parentheses, and its square must encompass the entire curvature.')
item(350,'P000579, action display','construction','The Yang--Mills curvature-squared action',r'The displayed action contains \(\partial_\alpha b_{\alpha\beta}-\partial_\beta b_\alpha-[b_\alpha,b_\beta]^2\) inside an incomplete trace parenthesis.',r'Fix a compact Lie group, an invariant positive inner product on its Lie algebra, and a connection \(A=\sum_\alpha A_\alpha dx^\alpha\) on Euclidean four-space. In the convention \(F_A=dA+A\wedge A\), \(F_{\alpha\beta}=\partial_\alpha A_\beta-\partial_\beta A_\alpha+[A_\alpha,A_\beta]\), and \(S(A)=(2g^2)^{-1}\int\langle F_A,F_A\rangle\,d^4x\), for fields for which the integral exists. A change of Lie-algebra convention may change the commutator sign, but the whole curvature is squared.',r'\citet[Eq.~(4) and the field-equations section]{yangmills1954conservation} gives the curvature and invariant Lagrangian. The theory predates this lecture by twenty years. The manuscript display cannot literally be a curvature-squared action and requires an explicit emendation.',refs=['yangmills1954conservation'],cls='E',literal='false as written',development='annotated',reconstruction=r'The invariant inner product, Euclidean convention and full outer square are editorial repairs. No existence theorem for the quantized theory is present.')
item(350,'P000579, connection and Riemann-curvature comparison','definition','Gauge potentials as local connection forms',r'An element of a Lie algebra at every point is identified with a connection; taking the coefficients to be Christoffel symbols gives the curvature tensor. The fibre is called a Lie algebra, with SU(2) named as example.',r'A connection is locally a Lie-algebra-valued one-form, not merely one Lie-algebra element at each point. On overlaps its local forms obey the affine gauge-transformation law. Its curvature is a two-form valued in the adjoint bundle; the analogous construction for a linear connection on the tangent bundle yields the Riemann curvature tensor. The Lie algebra for the named group is \(\mathfrak{su}(2)\).',r'The standard connection-curvature dictionary is reviewed in \citet[\S2, Eq.~(2.10)]{chernsimons1974characteristic}; Yang--Mills gauge covariance is already in \citet[Eq.~(3)]{yangmills1954conservation}. Both are earlier than21October1974.',refs=['chernsimons1974characteristic','yangmills1954conservation'],cls='E',literal='correct with missing hypotheses',reconstruction=r'The one-form index, overlap law and distinction between SU(2) and its Lie algebra correct the notebook\textquotesingle s compressed dictionary.')
item(350,'P000579, final Pontryagin expression','construction','The quadratic curvature form representing a Pontryagin class',r'The contracted expression \(R^b_{a,\delta_1\delta_2}R^a_{b,\delta_3\delta_4}\) is labelled a Pontryagin class.',r'For a real vector bundle with a metric connection and skew-symmetric curvature matrix \(\Omega\), the closed four-form \(-\tfrac1{8\pi^2}\operatorname{tr}(\Omega\wedge\Omega)\) represents the real image of \(p_1\). The written component contraction supplies the coefficient pattern only after alternating the four differential indices. A trace in a different group representation has a different normalization; for the fundamental complex rank-two \(SU(2)\) bundle one normally speaks of the second Chern class.',r'This is the Chern--Weil theorem, reviewed in \citet[Theorem2.12 and Eq.~(5.7)]{chernsimons1974characteristic}, publishedJanuary1974 and explicitly presented there as established connection theory. No new characteristic-class construction is asserted on the notebook page.',refs=['chernsimons1974characteristic'],cls='E',literal='correct with missing hypotheses',reconstruction=r'The exterior product, normalization, real bundle and de Rham representative are necessary to turn the component mnemonic into a precise statement.')
corr('P000579','Yang--Mills action display',r'\(\operatorname{Sp}(\partial_\alpha b_{\alpha\beta}-\partial_\beta b_\alpha-[b_\alpha,b_\beta]^2)\).',r'Use the trace or invariant inner product of the square of the whole curvature \(\partial_\alpha b_\beta-\partial_\beta b_\alpha\pm[b_\alpha,b_\beta]\), with paired indices and the chosen sign convention.',r'The scan has an extra alpha on the first potential and the exponent is adjacent to the commutator bracket. Yang--Mills1954, Eq.(4) and its Lagrangian, fixes the mathematical structure; this is an emendation of an incomplete notebook formula.')
corr('P000579','Lie-algebra fibre example',r'The fibre is a Lie algebra, for example SU(2).',r'The Lie algebra is \(\mathfrak{su}(2)\); SU(2) is its compact Lie group.',r'The scan uses uppercase SU(2) in a sentence about an algebra. The surrounding connection discussion requires a Lie-algebra-valued one-form.')
save()

# Record 351: the lecture ends on P583, before the next meeting heading.
talk(351,'1974-10-28','M. I. Graev','P000580-P000585','Irreducible representations of current groups and continuous tensor products',r'P000580--P000583 describes the Vershik--Gelfand--Graev construction for continuous maps from an interval to \(SL_2(\mathbb R)\). Complementary-series representations are embedded compatibly under successive subdivisions; a second realization uses formal coherent vectors and a logarithmic kernel. The detailed construction was already published in1973, and is therefore expository in this1974 lecture. The reference to Functional Analysis, volume2, number1, points instead to the earlier1968 Gelfand--Graev paper. Gelfand\textquotesingle s intervening question about Kolmogorov dimension and the drawing of negative squares lack enough normalization data for a unique identification.')
item(351,'P000580, matrix and programme','definition','The interval current group',r'The matrix entries of \(g(x)\) are continuous real functions on \([0,1]\), with \(\det g(x)=1\). The announced method of constructing irreducible representations is compared with integration.',r'Let \(G^X=C([0,1],SL_2(\mathbb R))\) with pointwise multiplication and the uniform topology. A unitary representation is understood to be strongly continuous. The construction recorded here factors through the pointwise quotient \(PSL_2(\mathbb R)\), so it is not required to detect central sign-valued currents.',r'This is the precise setup of \citet[Introduction and \S2]{vershikgelfandgraev1973functions}, received15June1973 and published1973. The notebook\textquotesingle s volume2, number1 citation identifies \citet{gelfandgraev1968quaternion}, received16October1967; it is a precursor, not the publication containing every formula on these pages.',refs=['vershikgelfandgraev1973functions','gelfandgraev1968quaternion'],cls='E',reconstruction=r'Uniform topology, strong continuity and the central quotient are explicit. The1968 precursor was checked bibliographically; the1973 construction was read in full relevant sections.')
item(351,'P000581, two-point picture','construction','Finite evaluation representations and tensor products',r'Gelfand replaces the interval by two points and lets \(g(x_1),g(x_2)\) act separately in \(H_1\otimes H_2\).',r'At distinct points \(x_1,\ldots,x_r\), choose irreducible unitary representations \(\pi_j\) of \(SL_2(\mathbb R)\). The formula \(\pi(g)=\bigotimes_j\pi_j(g(x_j))\) defines an irreducible unitary current-group representation. Evaluation onto the finite product is surjective because this Lie group is connected and the interval permits interpolation. Conversely, irreducible representations of the finite product decompose as outer tensor products because \(SL_2(\mathbb R)\) is type I.',r'The finite-product representation statement appears explicitly in \citet[\S1.3, Eq.~(14)]{vershikgelfandgraev1973functions}. It is background for the continuous tensor product, and recurs from1969-180.4.',refs=['vershikgelfandgraev1973functions'],speaker='I. M. Gelfand',literal='correct with missing hypotheses',reconstruction=r'Distinct evaluation points, irreducibility and the distinction between an outer tensor product and restriction to the diagonal subgroup are supplied.')
item(351,'P000581, Abelian example','construction','Characters and distributions, with the circle-valued qualification',r'For \(g(x)=e^{i\alpha(x)}\), an irreducible representation is written \(e^{i\ell(\alpha)}\), with \(\ell\) a linear functional; smooth test functions give distributions.',r'For the additive group of real smooth functions, continuous unitary characters are \(\alpha\mapsto e^{i\ell(\alpha)}\), with \(\ell\) a real continuous linear functional. Such functionals are distributions. To descend this formula to \(C^\infty([0,1],S^1)\), require \(\ell(1)\in\mathbb Z\), since two smooth lifts differ by a constant integral multiple of \(2\pi\). For continuous test functions the appropriate continuous dual consists of signed measures, rather than arbitrary distributions.',r'\citet[Introduction, pp.~87--88]{vershikgelfandgraev1973functions} uses the additive real current group, for which the formula has no period obstruction. The notebook\textquotesingle s circle notation requires the extra integrality condition. Related earlier occurrence:1969-180.9.',refs=['vershikgelfandgraev1973functions'],speaker='I. M. Gelfand',literal='correct with missing hypotheses',development='annotated',reconstruction=r'The distinction between the additive group and its circle-valued quotient, and the dependence on the test-function topology, are editorial qualifications.')
item(351,'P000581, uniformity question','question','A spatially uniform irreducible current-group representation',r'Gelfand asks whether there is an irreducible representation \ru{которое всюду устроено одинаково}.',r'For \(X=[0,1]\), \(G=PSL_2(\mathbb R)\), and a positive multiple \(m=\lambda\,dx\) of Lebesgue measure, construct a nontrivial irreducible strongly continuous representation of \(C(X,G)\) whose equivalence class is invariant under measure-preserving transformations of \(X\) that act on the chosen current group by pullback. In the continuous model these transformations may be taken to be measure-preserving homeomorphisms; the step-function construction accommodates the corresponding measurable formulation.',r'This existence question is answered by \citet[Theorems2.2, 3.3 and3.4]{vershikgelfandgraev1973functions}, already published in1973. The result is related to1969-180.2 and GP-1969-02, but only the earlier title is available: neither identity of their hypotheses nor resolution of the broader earlier problem is asserted.',refs=['vershikgelfandgraev1973functions'],cls='E',speaker='I. M. Gelfand',literal='correct with missing hypotheses',problem='GP-1974-14',reconstruction=r'Uniformity is interpreted through the measure-invariance property explicitly stated in the matching paper. This is an existence theorem for the specified group and topology, not a classification of all current-group representations.',status='As of November2026, solved in the stated PSL2(R), uniform-topology setting by the1973 multiplicative-integral construction. The classifying problem GP-1969-01 and the broader interval-support question GP-1969-02 are not thereby declared solved.')
item(351,'P000581, complementary-series norm and final action','construction','The complementary series in the real-line model',r'For \(0<\lambda<1\), \(\|f\|_\lambda^2=\iint |t-s|^{-\lambda}f(t)\overline{f(s)}\,dt\,ds\), and \(T_\lambda(g)f(t)=f((\alpha t+\gamma)/(\beta t+\delta))|\beta t+\delta|^{\lambda-2}\).',r'Complete a suitable dense test-function space in the positive kernel norm. The displayed operators extend to irreducible unitary representations for \(0<\lambda<1\), and factor through \(PSL_2(\mathbb R)\). Positivity can be seen from the Fourier multiplier \(c_\lambda|\xi|^{\lambda-1}\), with \(c_\lambda>0\). The completed space can contain generalized functions and is not simply a pointwise class of ordinary functions with an absolutely convergent integral.',r'Exact real-line formulas in \citet[\S1.1, Eqs.~(3)--(4)]{vershikgelfandgraev1973functions}; the authors describe this as the established supplementary series. The parameter interval is the one used for the integral kernel, and does not exhaust equivalent realizations obtained by continuation.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses',reconstruction=r'Completion, the dense test space and the row-vector convention for the fractional-linear transformation are made explicit.')
item(351,'P000581, representations close to one','claim','The trivial representation is an accumulation point',r'Gelfand stresses the existence of infinite-dimensional representations close to1; a second parameter is written \(\rho\approx1\), beside \(\rho=1\) labelled the identity representation.',r'The spherical matrix coefficients of the complementary series tend to1 as \(\lambda\downarrow0\), uniformly on compact subsets of the group, after normalizing the spherical vector. Thus the trivial representation is not isolated in the unitary dual. An endpoint pullback formula with exponent0 is not itself trivial on every function: the trivial representation is obtained through the appropriate invariant subspace or quotient.',r'\citet[Introduction and Lemma1.1]{vershikgelfandgraev1973functions} gives precisely the limiting spherical function. The two notebook parameters describe endpoint realizations and must not be equated without a convention change.',refs=['vershikgelfandgraev1973functions'],speaker='I. M. Gelfand',literal='correct with missing hypotheses',reconstruction=r'Closeness is stated in terms of matrix coefficients, not operator-norm convergence of operators on unidentified varying Hilbert spaces.')
item(351,'P000581, Kolmogorov-dimension intervention','question','An unidentified notion of representation dimension',r'The page labels a \ru{Задача} about dimension in Kolmogorov\textquotesingle s sense, refers to \ru{один японец}, and tentatively equates this dimension with a multiplier of Plancherel measure after choosing a kernel.',r'The notes do not define the dimension, the kernel, its normalization, the reference measure in the Plancherel decomposition, or the named author. Metric entropy dimension, formal degree and spectral multiplicity are different notions. No precise equality or research problem can therefore be recovered uniquely.',r'The matching current-group paper \citet{vershikgelfandgraev1973functions} does not supply this intervening definition. Searches for the Russian and English combinations of Kolmogorov dimension, Plancherel measure and representations produced no verified exact identification. Araki\textquotesingle s appearance elsewhere in current-group literature is insufficient to identify the unnamed Japanese mathematician.',refs=['vershikgelfandgraev1973functions'],cls='F',speaker='I. M. Gelfand',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',status='As of November2026, the intended dimension and reference remain unidentified. This is retained as an unresolved historical reading, with no fabricated formal-degree theorem and no problem-index entry.')
item(351,'P000581, homogeneous-polynomial comparison','construction','Finite-dimensional symmetric-power representations',r'The substitution \(f(x_1,x_2)\mapsto f(\alpha x_1+\beta x_2,\gamma x_1+\delta x_2)\) is applied to homogeneous polynomials of degree \(n\), with weight \(n\) said to approximate dimension.',r'The space of homogeneous polynomials of degree \(n\ge0\) in two variables has basis \(x_1^n,x_1^{n-1}x_2,\ldots,x_2^n\), and dimension \(n+1\). Linear substitution, using inverse or right-action convention consistently, gives the symmetric-power representation of \(SL_2\). Over \(\mathbb C\) it is irreducible; for the real noncompact group and \(n>0\) it is not a finite-dimensional unitary representation with a positive invariant norm.',r'This is the elementary algebraic comparison preceding the unitary construction. The notebook does not cite a distinct theorem. Its role is contrasted with the infinite-dimensional unitary representations in \citet[\S1.1]{vershikgelfandgraev1973functions}; the dimension \(n+1\) follows directly by counting the displayed monomial basis.',refs=['vershikgelfandgraev1973functions'],speaker='I. M. Gelfand',literal='correct with missing hypotheses',match='partial',verification='indirect',reconstruction=r'The exact dimension and the nonunitary character of the finite-dimensional nontrivial examples are supplied; weight and dimension are not identified as equal.')
item(351,'P000581, lambda-zero norm and invariant integral','construction','The endpoint invariant functional and its trivial quotient',r'At \(\lambda=0\), the norm degenerates to \(|\int f(t)\,dt|^2\); the last display says that integration is invariant under the exponent−2 fractional-linear action.',r'On a suitable test space the limiting form is \(B_0(f,h)=(\int f)\overline{(\int h)}\). Its kernel is the codimension-one invariant subspace of zero-integral functions. The quotient is the trivial one-dimensional representation, since change of variables gives \(\int T_0(g)f=\int f\). The zero-integral subspace obtains a different nondegenerate invariant form from the first derivative of the kernel at0; it is not given a positive norm by the zero form itself.',r'\citet[\S6.3, p.~128]{vershikgelfandgraev1973functions} explicitly uses this invariant functional and its kernel to build the logarithmic model. The elementary endpoint calculation links the two realizations on the notebook page.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses',reconstruction=r'The invariant subspace and the one-dimensional quotient are distinguished; this removes the apparent claim that the action on the entire test space becomes trivial.')
item(351,'P000581, analytic-continuation diagram','remark','Negative squares in an incompletely normalized continuation',r'A line marked0,1,2,3,4 has a crossed annotation between1 and2, then one negative square between2 and3 and two between3 and4.',r'A distributional analytic continuation of a kernel form requires its scalar normalization, domain, treatment at poles, and any moment conditions or quotient. Those data are absent here. The drawing therefore does not determine a signature theorem. In the standard normalized circle model the supplementary series also has a positive realization for \(1<\lambda<2\), equivalent to the parameter \(2-\lambda\).',r'The latter positive continuation is stated in \citet[\S1.1, p.~90, footnote1]{vershikgelfandgraev1973functions}. It explains why the crossed1--2 label should not be restored. No verified source was found for the exact subsequent negative-square counts under the unspecified notebook normalization.',refs=['vershikgelfandgraev1973functions'],cls='F',literal='not determinable',match='partial',verification='unresolved lead',confidence='low',status='As of November2026, the positive complementary-series continuation is known, but the exact indefinite form behind the sketch is unidentifiable. The numerical signature labels are preserved as source evidence without being promoted to a theorem.')
item(351,'P000582, successive interval diagrams','construction','Dyadic refinement of the step-current group',r'The constant subgroup is \(G\), the two-half subgroup is \(G^2\), then \(G^4\), and so on, with representations on tensor products of \(H_{\lambda/2^n}\).',r'For the dyadic partition \(\mathcal P_n\) of the interval and \(m=\lambda dx\), \(0<\lambda<1\), each cell has measure \(\lambda/2^n\). Diagonal duplication embeds \(G^{2^n}\) into \(G^{2^{n+1}}\). The associated outer tensor product acts in \(\mathcal H_n=\bigotimes_{j=1}^{2^n}H_{\lambda/2^n}\). Dyadic step functions approximate every continuous current uniformly, but an arbitrary step function is not itself a continuous current.',r'This is the dyadic specialization of the directed Borel-partition construction in \citet[\S2.1--2]{vershikgelfandgraev1973functions}. The distinction between the step group and the continuous group is explicit in that paper.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses',reconstruction=r'The measure scaling and diagonal embeddings are supplied; the inductive union is not identified set-theoretically with the continuous-current group.')
item(351,'P000582, supplementary summand once','theorem','Multiplicity one under diagonal restriction',r'The notes state \(H_{\lambda/2}\otimes H_{\lambda/2}=H_\lambda\oplus\text{rest}\), with \(H_\lambda\) occurring once.',r'If \(a,b>0\) and \(a+b<1\), the restriction of \(T_a\otimes T_b\) from \(G\times G\) to the diagonal \(G\) contains \(T_{a+b}\) with multiplicity one. The remaining decomposition contains only principal continuous and discrete series. Consequently the required intertwining isometry is unique up to a scalar of absolute value1.',r'Exact statement in \citet[Theorem1.4]{vershikgelfandgraev1973functions}, which attributes the tensor-product decomposition to Pukanszky\textquotesingle s1961 work. The1973 paper is the directly read primary source for this use; the original1961 proof was not checked here.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses',reconstruction=r'Restriction to the diagonal subgroup is essential; the tensor product remains irreducible as an outer representation of the full product group.')
item(351,'P000582, delta-function embedding','construction','The isometric diagonal delta embedding',r'The intertwiner is written \(f(t)\mapsto f(t)\delta(t-s)\), labelled a unitary embedding.',r'For \(a,b>0\), \(a+b<1\), the distribution \(f(t)\delta(t-s)\) belongs to the completed kernel tensor space and defines an isometry \(H_{a+b}\hookrightarrow H_a\otimes H_b\). Pairing two such diagonal distributions multiplies the kernels to give \(|t-s|^{-(a+b)}\). This is an isometric injection, not a surjective unitary isomorphism and not a claim that delta is an ordinary \(L^2\) function.',r'\citet[Lemmas1.7--1.8 and Theorems1.6--1.7]{vershikgelfandgraev1973functions} gives the precise distributional interpretation and coherent multiple embeddings. The explicit delta formula removes the otherwise arbitrary phase choice under refinement.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses')
item(351,'P000582, completed limit and extension','theorem','An irreducible continuous tensor-product representation',r'The iterated tensor spaces are nested, their inductive limit is completed, and the step-function representation is said to extend to continuous functions.',r'Use compatible isometric intertwiners satisfying composition under refinement, then complete \(\bigcup_n\mathcal H_n\). This produces a unitary step-current representation. Matrix-coefficient continuity in the uniform topology permits a unique strongly continuous extension to continuous currents. With the finite positive measure used here, the multiplicity-one construction yields irreducibility; irreducibility does not follow merely from the existence of an arbitrary inductive limit.',r'\citet[Theorems2.1--2.2, Lemma2.2 and Theorem3.3]{vershikgelfandgraev1973functions} proves compatibility, independence of phase choices, irreducibility and extension. These are already1973 results, not new1974 announcements.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses',problem='GP-1974-14',reconstruction=r'Compatibility, the topology in which continuity is checked, and the extra irreducibility argument are made explicit.')
item(351,'P000582-P000583, tilde and logarithmic form','construction','The centered logarithmic Hilbert space',r'The exponential scalar product uses \(-\log|t_1-t_2|\). The following page writes \(\widetilde f(x,t)=f(x,t)-1/[\pi(1+x^2)]\), although \(\int f(x,t)\,dt=1\).',r'Set \(\rho(t)=1/[\pi(1+t^2)]\) and \(h_x(t)=f(x,t)-\rho(t)\), so \(\int h_x=0\). On real zero-integral test functions define \(B(h,k)=-\iint\log|t-s|h(t)k(s)\,dt\,ds\). Its completion is a real Hilbert space; for complex functions insert conjugation in the second argument. The form arises by differentiating \(|t-s|^{-\lambda}\) at0 after the constant term has vanished.',r'Exact line-model construction in \citet[\S6.3, p.~128]{vershikgelfandgraev1973functions}. The variable in the Cauchy density is \(t\), not the interval coordinate \(x\). With the written \(x\), the subtracted function is constant in \(t\) and is not integrable, so the centering cannot work.',refs=['vershikgelfandgraev1973functions'],literal='false as written',development='annotated',reconstruction=r'The real-label version matches the paper; sesquilinear complexification is stated separately. Smoothness and decay may first be imposed on a dense test space before Hilbert completion.')
item(351,'P000582, formal combinations and exponential product','construction','Formal coherent vectors rather than ordinary functions',r'Finite formal linear combinations of the labels \(f(x,t)\) are introduced; the notes emphasize that the symbol labelled by zero need not be the zero vector.',r'Let \(\mathcal K=L^2(X,m;H_0)\), where \(H_0\) is the centered logarithmic Hilbert space. For real \(h\in\mathcal K\), introduce a formal vector \(e(h)\) and define \(\langle e(h),e(k)\rangle=\exp\langle h,k\rangle_{\mathcal K}\). Extend sesquilinearly, quotient any null vectors and complete. The exponential kernel is positive by its tensor-power series. In particular \(e(0)\) has norm1, although the label0 is the zero vector of \(\mathcal K\).',r'\citet[\S6.1, Lemma6.2, and \S6.3]{vershikgelfandgraev1973functions} gives this construction and its logarithmic integral form. It also recurs from the exponential-Hilbert-space discussion indexed as1969-180.6; no identity with every earlier model is assumed.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses',reconstruction=r'The label map is nonlinear. Distinct variables \(t_1,t_2\) are required in the two kernel factors; the measure \(m\) records the parameter of the representation.')
item(351,'P000583, representation display','construction','The scalar cocycle restoring unitarity',r'The endpoint fractional-linear action is multiplied by an unspecified \(\lambda(g,f)\).',r'In the real-label model put \(b_g=T_0(g)\rho-\rho\), \(A_gh=T_0(g)h\), and let \(Q\) be the inner product after integration over \(X\). Then an explicit normalized action is \[U_ge(h)=\exp\{-Q(A_gh,b_g)-\tfrac12Q(b_g,b_g)\}\,e(A_gh+b_g).\] The cocycle identity \(b_{g_1g_2}=b_{g_1}+A_{g_1}b_{g_2}\) makes this an ordinary unitary representation for the real model. Omitting the scalar generally fails to preserve the exponential kernel.',r'\citet[\S6.1, Lemmas6.1--6.3; \S6.3 and Theorem6.2]{vershikgelfandgraev1973functions} provides the multiplier and proves equivalence with the preceding irreducible construction. Complex holomorphic restrictions can instead produce projective representations; they are not what this unqualified real-line display specifies.',refs=['vershikgelfandgraev1973functions'],literal='correct with missing hypotheses',reconstruction=r'The explicit multiplier and the ordinary-versus-projective distinction are supplied from the matching construction; the notebook records only the unnamed scalar factor.')
P.append(dict(id='GP-1974-14',title='A measure-invariant irreducible representation of the PSL2 current group',statement=r'For \(C([0,1],PSL_2(\mathbb R))\) in the uniform topology, construct a nontrivial irreducible strongly continuous unitary representation whose equivalence class is unchanged by pullback along measure-preserving transformations acting on the current group, for a fixed positive Lebesgue measure.',occurrences=['1974-351.4','1974-351.14'],status=r'As of November2026, solved in this precise scope by the1973 multiplicative integral of complementary-series representations; see \citet[Theorems2.2, 3.3--3.4]{vershikgelfandgraev1973functions}. The earlier titles1969-180.2/GP-1969-02 and1969-180.1/GP-1969-01 concern related existence and classification questions, but their full formulations are unavailable here, so they are not merged or declared solved.',status_date='2026-11',refs=['vershikgelfandgraev1973functions']))
corr('P000581','Endpoint invariant-integral differential',r'\(\int f(t)\,dx\).',r'\(\int f(t)\,dt\).',r'The scan explicitly uses t in the integrand and dx on the left, but dt in the change-of-variables expression on the right. The endpoint invariant functional integrates the line coordinate t.')
corr('P000582','Arguments of the exponential-kernel factors',r'Both factors are written \(\widetilde f_i(x,t)\), with differentials \(dt_1dt_2dx\).',r'Use \(\widetilde f_1(x,t_1)\widetilde f_2(x,t_2)\) for real labels; conjugate the second factor in the complex-label formulation.',r'The scan has the repeated unsubscripted t. The matching VGG1973, Section6.3, uses separate line variables and real functions, with complex coefficients only in the formal span.')
corr('P000583','Centering density',r'\(\widetilde f(x,t)=f(x,t)-1/[\pi(1+x^2)]\).',r'\(\widetilde f(x,t)=f(x,t)-1/[\pi(1+t^2)]\).',r'The scan unmistakably has x squared. The constant-in-t subtraction is nonintegrable and cannot make the t-integral zero. VGG1973, Section6.3, p.128, explicitly uses the Cauchy density in t.')
corr('P000580','Functional Analysis volume2 number1 citation',r'The page cites Functional Analysis, volume2, number1 beside the current-group programme.',r'Retain this citation as the1968 Gelfand--Graev precursor; identify the detailed tensor and logarithmic-kernel construction with Vershik--Gelfand--Graev1973, RMS28(5),87--132.',r'Math-Net faa2751 identifies the1968 paper, received16October1967. VGG1973 cites it as reference1 and says that its integral construction goes beyond the earlier finite-support examples.',typ='provenance')
